import { cloneRange, inRange } from '../core/coordinates';
import { moveRuleRanges, shiftRuleRanges } from './rule-ranges';
import {
  Axis,
  DataValidationKind,
  DataValidationOperator,
  DataValidationRule,
  Ref,
} from '../core/types';
import { inferInput } from './input';

export const CHECKBOX_TRUE = 'TRUE';
export const CHECKBOX_FALSE = 'FALSE';

const Kinds = new Set<DataValidationKind>(['checkbox', 'list', 'date']);

/**
 * `dateValidationOperandCount` returns how many comparison operands an
 * operator consumes: 0 for `dateValid`, 2 for between/not-between, else 1.
 */
export function dateValidationOperandCount(op: DataValidationOperator): number {
  if (op === 'dateValid') return 0;
  if (op === 'dateBetween' || op === 'dateNotBetween') return 2;
  return 1;
}

/**
 * `toIsoDateOperand` normalizes a raw operand to an ISO `yyyy-mm-dd` string via
 * the shared input parser, or returns undefined when it is not a date.
 */
function toIsoDateOperand(raw: string | undefined): string | undefined {
  if (typeof raw !== 'string' || raw.trim() === '') return undefined;
  const inferred = inferInput(raw.trim());
  // `inferInput` returns the raw string for a datetime (`yyyy-mm-dd HH:MM:SS`);
  // keep only the `yyyy-mm-dd` date part so an operand is always a pure ISO date.
  return inferred.type === 'date' ? inferred.value.slice(0, 10) : undefined;
}

/**
 * `normalizeListOptions` trims each option, drops empty entries, and dedupes
 * (keeping first occurrence) — the canonical form of a list rule's options.
 */
export function normalizeListOptions(options: string[] | undefined): string[] {
  if (!Array.isArray(options)) {
    return [];
  }
  const seen = new Set<string>();
  const result: string[] = [];
  for (const raw of options) {
    const value = typeof raw === 'string' ? raw.trim() : '';
    if (!value || seen.has(value)) {
      continue;
    }
    seen.add(value);
    result.push(value);
  }
  return result;
}

/**
 * `normalizeDataValidationRule` validates a rule and returns a normalized
 * copy, or null if the rule is unusable (no id, unknown kind, no ranges). A
 * list rule additionally requires at least one usable option; its options are
 * trimmed/deduped and `showArrow` defaults to true.
 */
export function normalizeDataValidationRule(
  rule: DataValidationRule,
): DataValidationRule | null {
  if (!rule || !rule.id || !Kinds.has(rule.kind)) {
    return null;
  }
  if (!Array.isArray(rule.ranges) || rule.ranges.length === 0) {
    return null;
  }
  const cloned = cloneDataValidationRule(rule);
  if (cloned.kind === 'list') {
    const list = normalizeListOptions(cloned.list);
    if (list.length === 0) {
      return null;
    }
    cloned.list = list;
    cloned.showArrow = cloned.showArrow ?? true;
  }
  if (cloned.kind === 'date') {
    const op: DataValidationOperator = cloned.operator ?? 'dateValid';
    const need = dateValidationOperandCount(op);
    // Keep a fixed-length slot per operand, storing '' for a missing or
    // unparseable one. This preserves position (a blank lower bound never
    // promotes the upper bound to index 0) AND retains the other operands
    // (clearing one bound of a between-rule must not drop the still-filled
    // one). An empty slot makes the comparison incomplete, so `isValidDateValue`
    // degrades to "is a valid date" until every required operand is filled.
    const slots: string[] = [];
    for (let i = 0; i < need; i++) {
      slots.push(toIsoDateOperand(cloned.values?.[i]) ?? '');
    }
    cloned.operator = op;
    cloned.values = slots.some((slot) => slot !== '') ? slots : undefined;
    cloned.onInvalid = cloned.onInvalid ?? 'warning';
  }
  return cloned;
}

/**
 * `cloneDataValidationRule` returns a deep copy of the rule.
 */
export function cloneDataValidationRule(
  rule: DataValidationRule,
): DataValidationRule {
  return {
    ...rule,
    ranges: rule.ranges.map((r) => cloneRange(r)),
    list: rule.list ? [...rule.list] : undefined,
    values: rule.values ? [...rule.values] : undefined,
  };
}

/**
 * `resolveDataValidationAt` returns the last rule whose ranges contain the
 * point (last-matching-rule-wins, matching conditional-format precedence).
 */
export function resolveDataValidationAt(
  point: Ref,
  rules: DataValidationRule[],
): DataValidationRule | undefined {
  let resolved: DataValidationRule | undefined;
  for (const rule of rules) {
    if (rule.ranges.some((r) => inRange(point, r))) {
      resolved = rule;
    }
  }
  return resolved;
}

/**
 * `checkedValueOf` / `uncheckedValueOf` return the string a checked/unchecked
 * checkbox stores. Custom values fall back to boolean TRUE/FALSE for now.
 */
function checkedValueOf(rule: DataValidationRule): string {
  return rule.checkedValue ?? CHECKBOX_TRUE;
}
function uncheckedValueOf(rule: DataValidationRule): string {
  return rule.uncheckedValue ?? CHECKBOX_FALSE;
}

/**
 * `isCheckboxChecked` reports whether the cell value represents "checked". A
 * fully-default boolean checkbox (neither custom value set) matches TRUE/FALSE
 * case-insensitively — values arriving via xlsx import / REST API / external
 * paste can be lowercase and bypass `setData` normalization, and the formula
 * engine and input parser already treat TRUE/FALSE case-insensitively. As soon
 * as *either* custom value is set the rule is exact-match (Google Sheets
 * parity) — case-folding a custom `uncheckedValue` like `"true"` would
 * otherwise invert the state. The canonical `TRUE`/`FALSE` are compared without
 * allocating (this runs per visible checkbox per repaint); only a non-canonical
 * lowercase value hits the `toUpperCase` fallback.
 */
export function isCheckboxChecked(
  rule: DataValidationRule,
  value: string | undefined,
): boolean {
  if (value === undefined) return false;
  if (rule.checkedValue === undefined && rule.uncheckedValue === undefined) {
    if (value === CHECKBOX_TRUE) return true;
    if (value === CHECKBOX_FALSE) return false;
    return value.toUpperCase() === CHECKBOX_TRUE;
  }
  return value === checkedValueOf(rule);
}

/**
 * `toggleCheckboxValue` returns the value to write when the box is toggled.
 */
export function toggleCheckboxValue(
  rule: DataValidationRule,
  value: string | undefined,
): string {
  return isCheckboxChecked(rule, value)
    ? uncheckedValueOf(rule)
    : checkedValueOf(rule);
}

/**
 * `listOptionsOf` returns the normalized option list for a list rule.
 */
export function listOptionsOf(rule: DataValidationRule): string[] {
  return normalizeListOptions(rule.list);
}

/**
 * `isValidListValue` reports whether a cell value is permitted by a list rule.
 * Empty/cleared values are always allowed (Google Sheets parity — a rule never
 * blocks deleting a cell); a non-empty value must match one of the options,
 * comparing both sides trimmed so a stray typed space still matches. Compares
 * against `rule.list` directly (canonical after `normalizeDataValidationRule`)
 * without allocating, since this runs per visible cell per repaint.
 */
export function isValidListValue(
  rule: DataValidationRule,
  value: string | undefined,
): boolean {
  const trimmed = value?.trim() ?? '';
  if (trimmed === '') {
    return true;
  }
  const options = rule.list;
  if (!options) {
    return false;
  }
  return options.some((option) => option.trim() === trimmed);
}

/**
 * `isValidDateValue` reports whether a cell value satisfies a date rule. An
 * empty value is always allowed. The value and each operand are normalized to
 * an ISO `yyyy-mm-dd` string (which sorts chronologically) via the shared
 * input parser; a non-date value fails. When any required operand is still
 * blank (an unfilled slot), only "is a valid date" is enforced, so the rule
 * degrades safely rather than mis-flagging. A reversed `between`/`not between`
 * range (start > end) is swapped, matching Google Sheets.
 */
export function isValidDateValue(
  rule: DataValidationRule,
  value: string | undefined,
): boolean {
  if (value === undefined || value.trim() === '') return true;
  const iso = toIsoDateOperand(value);
  if (iso === undefined) return false;

  const op = rule.operator ?? 'dateValid';
  const need = dateValidationOperandCount(op);
  if (op === 'dateValid') return true;
  const operands = rule.values ?? [];
  // Any missing/blank required operand → validate "is a date" only.
  for (let i = 0; i < need; i++) {
    if (!operands[i]) return true;
  }

  const a = operands[0];
  switch (op) {
    case 'dateEquals':
      return iso === a;
    case 'dateBefore':
      return iso < a;
    case 'dateOnOrBefore':
      return iso <= a;
    case 'dateAfter':
      return iso > a;
    case 'dateOnOrAfter':
      return iso >= a;
    case 'dateBetween': {
      const lo = a <= operands[1] ? a : operands[1];
      const hi = a <= operands[1] ? operands[1] : a;
      return iso >= lo && iso <= hi;
    }
    case 'dateNotBetween': {
      const lo = a <= operands[1] ? a : operands[1];
      const hi = a <= operands[1] ? operands[1] : a;
      return iso < lo || iso > hi;
    }
    default:
      return true;
  }
}

/**
 * `describeDateRule` returns a short human phrase for a date rule's condition
 * (e.g. "must be after 2026-01-01", "must be between 2026-01-01 and
 * 2026-01-31"), so error messages can name the constraint instead of calling a
 * valid-but-out-of-range date "invalid". Falls back to "must be a valid date"
 * for `dateValid` or a rule whose operands are not yet fully filled. A reversed
 * between range is presented low→high to match how it is validated.
 */
export function describeDateRule(rule: DataValidationRule): string {
  const op = rule.operator ?? 'dateValid';
  const need = dateValidationOperandCount(op);
  const operands = rule.values ?? [];
  const complete =
    op === 'dateValid' || operands.slice(0, need).every((o) => !!o);
  if (!complete) return 'must be a valid date';
  const a = operands[0];
  const b = operands[1];
  const lo = a <= b ? a : b;
  const hi = a <= b ? b : a;
  switch (op) {
    case 'dateEquals':
      return `must be ${a}`;
    case 'dateBefore':
      return `must be before ${a}`;
    case 'dateOnOrBefore':
      return `must be on or before ${a}`;
    case 'dateAfter':
      return `must be after ${a}`;
    case 'dateOnOrAfter':
      return `must be on or after ${a}`;
    case 'dateBetween':
      return `must be between ${lo} and ${hi}`;
    case 'dateNotBetween':
      return `must not be between ${lo} and ${hi}`;
    default:
      return 'must be a valid date';
  }
}

/**
 * `isValidValueForRule` dispatches value validation by rule kind. A checkbox
 * rule never rejects a typed value; list and date delegate to their checks.
 */
export function isValidValueForRule(
  rule: DataValidationRule,
  value: string | undefined,
): boolean {
  if (rule.kind === 'list') return isValidListValue(rule, value);
  if (rule.kind === 'date') return isValidDateValue(rule, value);
  return true;
}

/**
 * `shiftDataValidationRules` remaps rules after row/column insert or delete.
 */
export function shiftDataValidationRules(
  rules: DataValidationRule[],
  axis: Axis,
  index: number,
  count: number,
): DataValidationRule[] {
  return shiftRuleRanges(
    rules,
    axis,
    index,
    count,
    normalizeDataValidationRule,
    cloneDataValidationRule,
  );
}

/**
 * `moveDataValidationRules` remaps rules after a row/column move.
 */
export function moveDataValidationRules(
  rules: DataValidationRule[],
  axis: Axis,
  src: number,
  count: number,
  dst: number,
): DataValidationRule[] {
  return moveRuleRanges(
    rules,
    axis,
    src,
    count,
    dst,
    normalizeDataValidationRule,
    cloneDataValidationRule,
  );
}

import {
  Grid,
  Cell,
  Ref,
  Range,
  SelectionType,
  CellStyle,
  ConditionalFormatRule,
  DataValidationRule,
  MergeSpan,
} from '../model/core/types';
import {
  RangeStylePatch,
  resolveRangeStyleAt,
} from '../model/worksheet/range-styles';
import { resolveConditionalFormatStyleAt } from '../model/worksheet/conditional-format';
import {
  isCheckboxChecked,
  isValidDateValue,
  isValidListValue,
  resolveDataValidationAt,
} from '../model/worksheet/data-validation';
import { DimensionIndex } from '../model/worksheet/dimensions';
import { formatValue } from '../model/worksheet/format';
import { defaultAlign } from '../model/worksheet/input';
import { Theme, ThemeKey, getThemeColor } from './theme';
import { parseRef, toColumnLabel, toSref } from '../model/core/coordinates';
import {
  DefaultCellWidth,
  DefaultCellHeight,
  RowHeaderWidth,
  CellBorderWidth,
  CustomCellBorderWidth,
  CellFontSize,
  CellLineHeight,
  CellPaddingX,
  CellPaddingY,
  HeaderTextAlign,
  BoundingRect,
  Position,
  FreezeState,
  NoFreeze,
  FreezeHandleThickness,
  toBoundingRect,
  getTextBlockHeight,
} from './layout';

type TextOverflowRenderData = {
  anchorToEndCol: Map<string, number>;
  hiddenVerticalBoundaries: Set<string>;
};

const TablerFilter2IconPath = 'M4 6h16 M6 12h12 M9 18h6';

// Hidden-indicator button sizing (shared with worksheet.ts hit detection)
export const HiddenBtnArrowSize = 3;
export const HiddenBtnArrowGap = 3;
export const HiddenBtnPadding = 3;
export const HiddenBtnRadius = 3;
export const HiddenBtnMargin = 1;

/**
 * `CheckboxBox` is the centered checkbox glyph rect within a cell.
 */
export type CheckboxBox = { left: number; top: number; size: number };

/**
 * `computeCheckboxBox` returns the centered checkbox glyph rect for a cell
 * rect, or null when the cell is too small to draw one. Shared by the render
 * pass and the click hit-test so the drawn glyph and the clickable target
 * never drift apart.
 */
export function computeCheckboxBox(rect: {
  left: number;
  top: number;
  width: number;
  height: number;
}): CheckboxBox | null {
  const { width, height } = rect;
  if (width <= 6 || height <= 6) {
    return null;
  }
  const size = Math.min(16, Math.max(11, Math.min(width, height) - 6));
  return {
    left: rect.left + (width - size) / 2,
    top: rect.top + (height - size) / 2,
    size,
  };
}

/**
 * `ListArrowBox` is the right-aligned dropdown-arrow glyph rect within a cell.
 */
export type ListArrowBox = { left: number; top: number; size: number };

/**
 * `computeListArrowBox` returns the right-aligned dropdown-arrow rect for a
 * cell rect, or null when the cell is too small. Shared by the render pass and
 * the click hit-test so the drawn arrow and the clickable target never drift.
 */
export function computeListArrowBox(rect: {
  left: number;
  top: number;
  width: number;
  height: number;
}): ListArrowBox | null {
  const { width, height } = rect;
  if (width <= 6 || height <= 6) {
    return null;
  }
  const size = Math.min(16, Math.max(11, Math.min(width, height) - 6));
  const margin = 2;
  // A right-aligned arrow needs the full glyph + margin to fit inside the cell;
  // on a very narrow column drawing it anyway would spill onto the neighbor
  // (glyph and hit-test both). Skip the arrow rather than overflow.
  if (width < size + margin) {
    return null;
  }
  return {
    left: rect.left + width - size - margin,
    top: rect.top + (height - size) / 2,
    size,
  };
}

/**
 * GridCanvas handles the rendering of the spreadsheet grid on a canvas element.
 */
export class GridCanvas {
  private canvas: HTMLCanvasElement;
  private theme: Theme;
  private static filterIconPath2D: Path2D | null | undefined;
  private static checkIconPath2D: Path2D | null | undefined;
  private static listArrowPath2D: Path2D | null | undefined;

  constructor(theme: Theme = 'light') {
    this.theme = theme;
    this.canvas = document.createElement('canvas');
    this.canvas.style.position = 'absolute';
    this.canvas.style.pointerEvents = 'none';
  }

  public getCanvas(): HTMLCanvasElement {
    return this.canvas;
  }

  public render(
    viewport: BoundingRect,
    scroll: Position,
    viewRange: Range,
    activeCell: Ref,
    grid?: Grid,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    selectionType?: SelectionType,
    selectionRange?: Range,
    freeze: FreezeState = NoFreeze,
    freezeHandleHover: 'row' | 'column' | null = null,
    colStyles?: Map<number, CellStyle>,
    rowStyles?: Map<number, CellStyle>,
    sheetStyle?: CellStyle,
    rangeStyles?: RangeStylePatch[],
    conditionalFormats?: ConditionalFormatRule[],
    merges?: Map<string, MergeSpan>,
    filterRange?: Range,
    filteredColumns?: Set<number>,
    hoveredFilterButtonCol: number | null = null,
    hiddenRows?: Set<number>,
    hiddenColumns?: Set<number>,
    hiddenIndicatorHover?: {
      axis: 'row' | 'column';
      boundary: number;
    } | null,
    zoom: number = 1,
    rowOrder?: string[],
    colOrder?: string[],
    commentCellKeys?: Set<string>,
    dataValidations?: DataValidationRule[],
  ): void {
    this.canvas.width = 0;
    this.canvas.height = 0;

    const ctx = this.canvas.getContext('2d')!;
    const ratio = window.devicePixelRatio || 1;

    this.canvas.width = viewport.width * ratio;
    this.canvas.height = viewport.height * ratio;
    this.canvas.style.width = viewport.width + 'px';
    this.canvas.style.height = viewport.height + 'px';
    ctx.scale(ratio * zoom, ratio * zoom);

    // When zoomed out, the logical drawing area exceeds the raw viewport.
    // Reassign so all subsequent drawing uses the effective dimensions.
    if (zoom !== 1) {
      viewport = {
        ...viewport,
        width: viewport.width / zoom,
        height: viewport.height / zoom,
      };
    }

    const [startID, endID] = viewRange;
    const mergeData = this.buildMergeRenderData(merges);
    const hasFrozen = freeze.frozenRows > 0 || freeze.frozenCols > 0;

    if (!hasFrozen) {
      // No freeze: render everything as before
      this.renderQuadrantCells(
        ctx,
        startID.r,
        endID.r + 1,
        startID.c,
        endID.c + 1,
        grid,
        scroll,
        rowDim,
        colDim,
        colStyles,
        rowStyles,
        sheetStyle,
        rangeStyles,
        conditionalFormats,
        mergeData,
        filterRange,
        filteredColumns,
        hoveredFilterButtonCol,
        rowOrder,
        colOrder,
        commentCellKeys,
        dataValidations,
      );
      this.renderColumnHeaders(
        ctx,
        startID.c,
        endID.c,
        scroll.left,
        RowHeaderWidth,
        viewport.width,
        activeCell,
        selectionType,
        selectionRange,
        rowDim,
        colDim,
      );
      this.renderRowHeaders(
        ctx,
        startID.r,
        endID.r,
        scroll.top,
        DefaultCellHeight,
        viewport.height,
        activeCell,
        selectionType,
        selectionRange,
        rowDim,
        colDim,
      );
    } else {
      const fw = freeze.frozenWidth;
      const fh = freeze.frozenHeight;
      const gx = freeze.gapX;
      const gy = freeze.gapY;
      const fr = freeze.frozenRows;
      const fc = freeze.frozenCols;
      const unfrozenRowStartIndex = fr + 1;
      const unfrozenColStartIndex = fc + 1;
      const startUnfrozenRow = Math.max(unfrozenRowStartIndex, startID.r);
      const startUnfrozenCol = Math.max(unfrozenColStartIndex, startID.c);

      // Compute scroll for unfrozen area: offset relative to first unfrozen row/col
      const unfrozenRowStart = rowDim
        ? rowDim.getOffset(unfrozenRowStartIndex)
        : fr * DefaultCellHeight;
      const unfrozenColStart = colDim
        ? colDim.getOffset(unfrozenColStartIndex)
        : fc * DefaultCellWidth;

      // Quadrant D (bottom-right): scrolled H + V — draw first (background)
      ctx.save();
      ctx.beginPath();
      ctx.rect(
        RowHeaderWidth + fw + gx,
        DefaultCellHeight + fh + gy,
        viewport.width - RowHeaderWidth - fw - gx,
        viewport.height - DefaultCellHeight - fh - gy,
      );
      ctx.clip();
      this.renderQuadrantCells(
        ctx,
        startUnfrozenRow,
        endID.r + 1,
        startUnfrozenCol,
        endID.c + 1,
        grid,
        {
          left: scroll.left + unfrozenColStart - fw - gx,
          top: scroll.top + unfrozenRowStart - fh - gy,
        },
        rowDim,
        colDim,
        colStyles,
        rowStyles,
        sheetStyle,
        rangeStyles,
        conditionalFormats,
        mergeData,
        filterRange,
        filteredColumns,
        hoveredFilterButtonCol,
        rowOrder,
        colOrder,
        commentCellKeys,
        dataValidations,
      );
      ctx.restore();

      // Quadrant B (top-right): frozen rows, scrolled H
      if (fr > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(
          RowHeaderWidth + fw + gx,
          DefaultCellHeight,
          viewport.width - RowHeaderWidth - fw - gx,
          fh,
        );
        ctx.clip();
        this.renderQuadrantCells(
          ctx,
          1,
          fr + 1,
          startUnfrozenCol,
          endID.c + 1,
          grid,
          { left: scroll.left + unfrozenColStart - fw - gx, top: 0 },
          rowDim,
          colDim,
          colStyles,
          rowStyles,
          sheetStyle,
          rangeStyles,
          conditionalFormats,
          mergeData,
          filterRange,
          filteredColumns,
          hoveredFilterButtonCol,
          rowOrder,
          colOrder,
          commentCellKeys,
          dataValidations,
        );
        ctx.restore();
      }

      // Quadrant C (bottom-left): scrolled rows, frozen cols
      if (fc > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(
          RowHeaderWidth,
          DefaultCellHeight + fh + gy,
          fw,
          viewport.height - DefaultCellHeight - fh - gy,
        );
        ctx.clip();
        this.renderQuadrantCells(
          ctx,
          startUnfrozenRow,
          endID.r + 1,
          1,
          fc + 1,
          grid,
          { left: 0, top: scroll.top + unfrozenRowStart - fh - gy },
          rowDim,
          colDim,
          colStyles,
          rowStyles,
          sheetStyle,
          rangeStyles,
          conditionalFormats,
          mergeData,
          filterRange,
          filteredColumns,
          hoveredFilterButtonCol,
          rowOrder,
          colOrder,
          commentCellKeys,
          dataValidations,
        );
        ctx.restore();
      }

      // Quadrant A (top-left): frozen R + C — draw last (foreground)
      if (fr > 0 && fc > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.rect(RowHeaderWidth, DefaultCellHeight, fw, fh);
        ctx.clip();
        this.renderQuadrantCells(
          ctx,
          1,
          fr + 1,
          1,
          fc + 1,
          grid,
          { left: 0, top: 0 },
          rowDim,
          colDim,
          colStyles,
          rowStyles,
          sheetStyle,
          rangeStyles,
          conditionalFormats,
          mergeData,
          filterRange,
          filteredColumns,
          hoveredFilterButtonCol,
          rowOrder,
          colOrder,
          commentCellKeys,
          dataValidations,
        );
        ctx.restore();
      }

      // Column headers — frozen columns (no scroll)
      if (fc > 0) {
        this.renderColumnHeaders(
          ctx,
          1,
          fc,
          0,
          RowHeaderWidth,
          RowHeaderWidth + fw,
          activeCell,
          selectionType,
          selectionRange,
          rowDim,
          colDim,
        );
      }
      // Column headers — unfrozen columns (scrolled)
      this.renderColumnHeaders(
        ctx,
        startUnfrozenCol,
        endID.c,
        scroll.left + unfrozenColStart - fw - gx,
        RowHeaderWidth + fw + gx,
        viewport.width,
        activeCell,
        selectionType,
        selectionRange,
        rowDim,
        colDim,
      );

      // Row headers — frozen rows (no scroll)
      if (fr > 0) {
        this.renderRowHeaders(
          ctx,
          1,
          fr,
          0,
          DefaultCellHeight,
          DefaultCellHeight + fh,
          activeCell,
          selectionType,
          selectionRange,
          rowDim,
          colDim,
        );
      }
      // Row headers — unfrozen rows (scrolled)
      this.renderRowHeaders(
        ctx,
        startUnfrozenRow,
        endID.r,
        scroll.top + unfrozenRowStart - fh - gy,
        DefaultCellHeight + fh + gy,
        viewport.height,
        activeCell,
        selectionType,
        selectionRange,
        rowDim,
        colDim,
      );

      // Freeze line separators
      this.renderFreezeLines(ctx, viewport, fw, fh, gx, gy);
    }

    // Render corner button (top-left intersection of row/column headers)
    const isAllSelected = selectionType === 'all';
    ctx.fillStyle = isAllSelected
      ? this.getThemeColor('headerSelectedBGColor')
      : this.getThemeColor('headerBGColor');
    ctx.fillRect(0, 0, RowHeaderWidth, DefaultCellHeight);
    ctx.strokeStyle = this.getThemeColor('cellBorderColor');
    ctx.lineWidth = CellBorderWidth;
    ctx.strokeRect(0, 0, RowHeaderWidth, DefaultCellHeight);

    // Render freeze drag handles
    this.renderFreezeHandles(ctx, freeze, freezeHandleHover);

    // Render hidden row/column indicators
    if (hiddenRows && hiddenRows.size > 0) {
      this.renderHiddenRowIndicators(
        ctx,
        viewRange[0].r,
        viewRange[1].r,
        scroll.top,
        DefaultCellHeight,
        viewport.height,
        rowDim,
        hiddenRows,
        hiddenIndicatorHover?.axis === 'row'
          ? hiddenIndicatorHover.boundary
          : null,
      );
    }
    if (hiddenColumns && hiddenColumns.size > 0) {
      this.renderHiddenColumnIndicators(
        ctx,
        viewRange[0].c,
        viewRange[1].c,
        scroll.left,
        RowHeaderWidth,
        viewport.width,
        colDim,
        hiddenColumns,
        hiddenIndicatorHover?.axis === 'column'
          ? hiddenIndicatorHover.boundary
          : null,
      );
    }
  }

  /**
   * Renders cells within a row/col range with the given scroll offset.
   */
  private renderQuadrantCells(
    ctx: CanvasRenderingContext2D,
    rowStart: number,
    rowEnd: number,
    colStart: number,
    colEnd: number,
    grid: Grid | undefined,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    colStyles?: Map<number, CellStyle>,
    rowStyles?: Map<number, CellStyle>,
    sheetStyle?: CellStyle,
    rangeStyles?: RangeStylePatch[],
    conditionalFormats?: ConditionalFormatRule[],
    mergeData?: {
      anchors: Map<string, MergeSpan>;
      coverToAnchor: Map<string, string>;
    },
    filterRange?: Range,
    filteredColumns?: Set<number>,
    hoveredFilterButtonCol: number | null = null,
    rowOrder?: string[],
    colOrder?: string[],
    commentCellKeys?: Set<string>,
    dataValidations?: DataValidationRule[],
  ): void {
    const styleCache = new Map<string, CellStyle | null>();
    const resolveCellStyle = (
      row: number,
      col: number,
      cell?: Cell,
    ): CellStyle | undefined => {
      const sref = toSref({ r: row, c: col });
      if (styleCache.has(sref)) {
        const cached = styleCache.get(sref);
        return cached || undefined;
      }

      const resolved = this.resolveEffectiveStyle(
        row,
        col,
        cell,
        sheetStyle,
        colStyles,
        rowStyles,
        rangeStyles,
        conditionalFormats,
      );
      styleCache.set(sref, resolved || null);
      return resolved;
    };

    // Extend the overflow detection range to the left so that text from
    // off-screen cells that overflows into the visible area is still drawn.
    const overflowColStart = Math.max(1, colStart - 20);
    const overflowData = this.buildTextOverflowRenderData(
      ctx,
      rowStart,
      rowEnd,
      overflowColStart,
      colEnd,
      grid,
      colDim,
      mergeData,
      resolveCellStyle,
    );
    const renderRefs = this.buildRenderableRefs(
      rowStart,
      rowEnd,
      colStart,
      colEnd,
      mergeData,
    );

    // Three-pass rendering: backgrounds first, then custom borders, then text.
    // This ensures text overflow into empty neighbor cells is not
    // overwritten by the neighbor's background fill.

    // Pass 1: Render all cell backgrounds and default grid borders.
    for (const { r: row, c: col } of renderRefs) {
      const sref = toSref({ r: row, c: col });
      const cell = grid?.get(sref);
      const mergeSpan = mergeData?.anchors.get(sref);
      const effectiveStyle = resolveCellStyle(row, col, cell);
      const hideLeftBorder = overflowData?.hiddenVerticalBoundaries.has(
        this.verticalBoundaryKey(row, col - 1),
      );
      const hideRightBorder = overflowData?.hiddenVerticalBoundaries.has(
        this.verticalBoundaryKey(row, col),
      );
      this.renderCellBackground(
        ctx,
        { r: row, c: col },
        cell,
        scroll,
        rowDim,
        colDim,
        effectiveStyle,
        mergeSpan,
        hideLeftBorder,
        hideRightBorder,
      );
    }

    // Pass 2: Render custom cell borders.
    for (const { r: row, c: col } of renderRefs) {
      const sref = toSref({ r: row, c: col });
      const cell = grid?.get(sref);
      const mergeSpan = mergeData?.anchors.get(sref);
      const effectiveStyle = resolveCellStyle(row, col, cell);
      this.renderCellCustomBorders(
        ctx,
        { r: row, c: col },
        scroll,
        rowDim,
        colDim,
        effectiveStyle,
        mergeSpan,
      );
    }

    // Pass 3: Render all cell text content (with overflow clipping).
    for (const { r: row, c: col } of renderRefs) {
      const sref = toSref({ r: row, c: col });
      const cell = grid?.get(sref);
      const mergeSpan = mergeData?.anchors.get(sref);
      const effectiveStyle = resolveCellStyle(row, col, cell);

      const dvRule = dataValidations
        ? resolveDataValidationAt({ r: row, c: col }, dataValidations)
        : undefined;
      if (dvRule && dvRule.kind === 'checkbox') {
        this.renderCellCheckbox(
          ctx,
          { r: row, c: col },
          dvRule,
          cell,
          scroll,
          rowDim,
          colDim,
          mergeSpan,
        );
        continue;
      }

      const overflowEndCol = overflowData?.anchorToEndCol.get(sref);
      this.renderCellContent(
        ctx,
        { r: row, c: col },
        cell,
        scroll,
        rowDim,
        colDim,
        effectiveStyle,
        grid,
        colEnd,
        mergeSpan,
        overflowEndCol,
      );

      // List (dropdown) rules keep their cell text but overlay a dropdown
      // arrow and, in warning mode, a red marker for out-of-list values.
      if (dvRule && dvRule.kind === 'list') {
        this.renderCellListControl(
          ctx,
          { r: row, c: col },
          dvRule,
          cell,
          scroll,
          rowDim,
          colDim,
          effectiveStyle,
          mergeSpan,
        );
      }

      // Date rules have no persistent glyph (GS parity); flag an invalid
      // value (non-date or out-of-bounds) with the same red corner marker
      // the list warning path uses. Computed at render time, never persisted.
      if (dvRule && dvRule.kind === 'date' && !isValidDateValue(dvRule, cell?.v)) {
        const rect = this.toCellRect(
          { r: row, c: col },
          scroll,
          rowDim,
          colDim,
          mergeSpan,
        );
        this.drawCornerMarker(ctx, rect.left + rect.width, rect.top, '#ea4335');
      }
    }

    // Pass 3b: Render text from off-screen overflow anchors whose text
    // spills into the visible viewport. These cells are outside the normal
    // renderRefs range, so they need an extra draw pass.
    if (overflowData) {
      for (const [sref, endCol] of overflowData.anchorToEndCol) {
        const ref = parseRef(sref);
        if (ref.c < colStart && endCol >= colStart) {
          const cell = grid?.get(sref);
          const effectiveStyle = resolveCellStyle(ref.r, ref.c, cell);
          this.renderCellContent(
            ctx,
            ref,
            cell,
            scroll,
            rowDim,
            colDim,
            effectiveStyle,
            grid,
            colEnd,
            undefined,
            endCol,
          );
        }
      }
    }

    // Pass 4: Render filter dropdown buttons inside filter header row cells.
    if (filterRange) {
      const headerRow = filterRange[0].r;
      if (headerRow >= rowStart && headerRow <= rowEnd) {
        const startCol = Math.max(colStart, filterRange[0].c);
        const endCol = Math.min(colEnd, filterRange[1].c);
        for (let col = startCol; col <= endCol; col++) {
          const sref = toSref({ r: headerRow, c: col });
          if (mergeData?.coverToAnchor.has(sref)) {
            continue;
          }
          const mergeSpan = mergeData?.anchors.get(sref);
          this.renderCellFilterButton(
            ctx,
            { r: headerRow, c: col },
            scroll,
            rowDim,
            colDim,
            mergeSpan,
            !!filteredColumns?.has(col),
            hoveredFilterButtonCol === col,
          );
        }
      }
    }

    // Pass 5: Render comment markers on cells with open threads.
    if (commentCellKeys && rowOrder && colOrder) {
      for (const { r: row, c: col } of renderRefs) {
        // Map numeric row/col indices to axis IDs
        const rowId = rowOrder[row - 1];
        const colId = colOrder[col - 1];
        if (!rowId || !colId) continue;

        const cellKey = `${rowId}|${colId}`;
        if (!commentCellKeys.has(cellKey)) continue;

        // Use the canonical cell-rect helper so the marker tracks scroll,
        // header offsets, and merged-cell anchoring exactly like cell content.
        const mergeSpan = mergeData?.anchors.get(toSref({ r: row, c: col }));
        const rect = this.toCellRect(
          { r: row, c: col },
          scroll,
          rowDim,
          colDim,
          mergeSpan,
        );
        this.drawCommentMarker(ctx, rect.left + rect.width, rect.top);
      }
    }
  }

  /**
   * Draws a 9x9 yellow right-triangle comment marker at the top-right corner of a cell.
   * The triangle is positioned with its right angle at the top-right corner.
   */
  private drawCommentMarker(
    ctx: CanvasRenderingContext2D,
    cellRight: number,
    cellTop: number,
  ): void {
    this.drawCornerMarker(ctx, cellRight, cellTop, '#fbbc04');
  }

  /**
   * Draws a 9x9 right-triangle marker at the top-right corner of a cell, with
   * its right angle at the corner. Shared by the comment marker (yellow) and
   * the data-validation warning marker (red).
   */
  private drawCornerMarker(
    ctx: CanvasRenderingContext2D,
    cellRight: number,
    cellTop: number,
    color: string,
  ): void {
    const MARKER_SIZE = 9;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cellRight, cellTop);
    ctx.lineTo(cellRight, cellTop + MARKER_SIZE);
    ctx.lineTo(cellRight - MARKER_SIZE, cellTop);
    ctx.closePath();
    ctx.fill();
  }

  /**
   * Builds render refs for a quadrant: all in-range non-covered cells plus
   * merged anchors whose blocks intersect this range even if the anchor itself
   * is outside the range.
   */
  private buildRenderableRefs(
    rowStart: number,
    rowEnd: number,
    colStart: number,
    colEnd: number,
    mergeData?: {
      anchors: Map<string, MergeSpan>;
      coverToAnchor: Map<string, string>;
    },
  ): Ref[] {
    const refs: Ref[] = [];
    const seen = new Set<string>();

    for (let row = rowStart; row <= rowEnd; row++) {
      for (let col = colStart; col <= colEnd; col++) {
        const sref = toSref({ r: row, c: col });
        if (mergeData?.coverToAnchor.has(sref)) {
          continue;
        }
        refs.push({ r: row, c: col });
        seen.add(sref);
      }
    }

    if (!mergeData) {
      return refs;
    }

    for (const [anchorSref, span] of mergeData.anchors) {
      if (seen.has(anchorSref)) {
        continue;
      }
      const anchor = parseRef(anchorSref);
      const mergeEndRow = anchor.r + span.rs - 1;
      const mergeEndCol = anchor.c + span.cs - 1;
      const intersects =
        anchor.r <= rowEnd &&
        mergeEndRow >= rowStart &&
        anchor.c <= colEnd &&
        mergeEndCol >= colStart;
      if (!intersects) {
        continue;
      }
      refs.push(anchor);
    }

    return refs;
  }

  /**
   * Renders column headers within a clip range.
   */
  private renderColumnHeaders(
    ctx: CanvasRenderingContext2D,
    colStart: number,
    colEnd: number,
    scrollLeft: number,
    clipLeft: number,
    clipRight: number,
    activeCell: Ref,
    selectionType?: SelectionType,
    selectionRange?: Range,
    _rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
  ): void {
    ctx.save();
    ctx.beginPath();
    ctx.rect(clipLeft, 0, clipRight - clipLeft, DefaultCellHeight);
    ctx.clip();

    for (let col = colStart; col <= colEnd; col++) {
      const colOffset = colDim
        ? colDim.getOffset(col)
        : DefaultCellWidth * (col - 1);
      const colWidth = colDim ? colDim.getSize(col) : DefaultCellWidth;
      if (colWidth <= 0) {
        continue;
      }
      const x = RowHeaderWidth + colOffset - scrollLeft;
      const y = 0;
      const isColSelected =
        selectionType === 'all' ||
        (selectionType === 'column' &&
          selectionRange &&
          col >= selectionRange[0].c &&
          col <= selectionRange[1].c);
      this.renderHeader(
        ctx,
        x,
        y,
        colWidth,
        DefaultCellHeight,
        toColumnLabel(col),
        activeCell.c === col,
        isColSelected || false,
      );
    }

    ctx.restore();
  }

  private renderCellFilterButton(
    ctx: CanvasRenderingContext2D,
    id: Ref,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    mergeSpan?: MergeSpan,
    active = false,
    hovered = false,
  ): void {
    const rect = this.toCellRect(id, scroll, rowDim, colDim, mergeSpan);
    const width = rect.width;
    const height = rect.height;
    if (width <= 6 || height <= 6) {
      return;
    }

    const buttonWidth = Math.min(16, Math.max(12, width - 4));
    const buttonHeight = Math.min(16, Math.max(12, height - 6));
    const left = rect.left + width - buttonWidth - 2;
    const top = rect.top + Math.max(3, (height - buttonHeight) / 2);

    if (active || hovered) {
      ctx.fillStyle = active
        ? this.getThemeColor('selectionBGColor')
        : this.getThemeColor('headerSelectedBGColor');
      ctx.fillRect(left, top, buttonWidth, buttonHeight);
    }

    const iconColor =
      active || hovered
        ? this.getThemeColor('resizeHandleColor')
        : this.getThemeColor('cellTextColor');
    const iconSize = Math.max(
      9,
      Math.min(12, Math.min(buttonWidth, buttonHeight) - 3),
    );
    const iconLeft = left + (buttonWidth - iconSize) / 2;
    const iconTop = top + (buttonHeight - iconSize) / 2;

    ctx.save();
    ctx.translate(iconLeft, iconTop);
    ctx.scale(iconSize / 24, iconSize / 24);
    ctx.strokeStyle = iconColor;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const path2d = this.getFilterIconPath2D();
    if (path2d) {
      ctx.lineWidth = 2;
      ctx.stroke(path2d);
    } else {
      // Fallback when Path2D is unavailable (e.g., some test environments).
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(4, 6);
      ctx.lineTo(20, 6);
      ctx.moveTo(6, 12);
      ctx.lineTo(18, 12);
      ctx.moveTo(9, 18);
      ctx.lineTo(15, 18);
      ctx.stroke();
    }
    ctx.restore();
  }

  private getFilterIconPath2D(): Path2D | null {
    if (typeof Path2D === 'undefined') {
      return null;
    }
    if (GridCanvas.filterIconPath2D === undefined) {
      GridCanvas.filterIconPath2D = new Path2D(TablerFilter2IconPath);
    }
    return GridCanvas.filterIconPath2D;
  }

  private renderCellCheckbox(
    ctx: CanvasRenderingContext2D,
    id: Ref,
    rule: DataValidationRule,
    cell: Cell | undefined,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    mergeSpan?: MergeSpan,
  ): void {
    const rect = this.toCellRect(id, scroll, rowDim, colDim, mergeSpan);
    const box = computeCheckboxBox(rect);
    if (!box) {
      return;
    }
    const { left, top, size: boxSize } = box;
    const checked = isCheckboxChecked(rule, cell?.v);

    ctx.save();
    if (checked) {
      ctx.fillStyle = this.getThemeColor('selectionBGColor');
      ctx.fillRect(left, top, boxSize, boxSize);

      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      const path = this.getCheckIconPath2D();
      if (path) {
        ctx.save();
        ctx.translate(left, top);
        ctx.scale(boxSize / 24, boxSize / 24);
        ctx.stroke(path);
        ctx.restore();
      } else {
        ctx.beginPath();
        ctx.moveTo(left + boxSize * 0.22, top + boxSize * 0.52);
        ctx.lineTo(left + boxSize * 0.42, top + boxSize * 0.72);
        ctx.lineTo(left + boxSize * 0.78, top + boxSize * 0.3);
        ctx.stroke();
      }
    } else {
      ctx.strokeStyle = this.getThemeColor('cellTextColor');
      ctx.lineWidth = 1.5;
      ctx.strokeRect(left + 0.5, top + 0.5, boxSize - 1, boxSize - 1);
    }
    ctx.restore();
  }

  private getCheckIconPath2D(): Path2D | null {
    if (typeof Path2D === 'undefined') {
      return null;
    }
    if (GridCanvas.checkIconPath2D === undefined) {
      // Check mark drawn in a 24×24 coordinate space.
      GridCanvas.checkIconPath2D = new Path2D('M5 12.5 L10 17.5 L19 7');
    }
    return GridCanvas.checkIconPath2D;
  }

  private getListArrowPath2D(): Path2D | null {
    if (typeof Path2D === 'undefined') {
      return null;
    }
    if (GridCanvas.listArrowPath2D === undefined) {
      // Chevron-down drawn in a 24×24 coordinate space.
      GridCanvas.listArrowPath2D = new Path2D('M6 9 L12 15 L18 9');
    }
    return GridCanvas.listArrowPath2D;
  }

  /**
   * `renderCellListControl` overlays the dropdown-arrow glyph on a list-ruled
   * cell (when `showArrow`) and, for a warning-mode rule, a red marker when the
   * current value is not one of the allowed options. Violation state is
   * computed here at render time and never persisted.
   */
  private renderCellListControl(
    ctx: CanvasRenderingContext2D,
    id: Ref,
    rule: DataValidationRule,
    cell: Cell | undefined,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    effectiveStyle?: CellStyle,
    mergeSpan?: MergeSpan,
  ): void {
    const rect = this.toCellRect(id, scroll, rowDim, colDim, mergeSpan);

    if (rule.showArrow !== false) {
      const box = computeListArrowBox(rect);
      if (box) {
        const { left, top, size } = box;
        // Mask any cell text under the arrow with the cell's background.
        ctx.save();
        ctx.fillStyle = effectiveStyle?.bg || this.getThemeColor('cellBGColor');
        ctx.fillRect(left, top, size, size);

        const iconSize = Math.max(9, Math.min(14, size - 2));
        const iconLeft = left + (size - iconSize) / 2;
        const iconTop = top + (size - iconSize) / 2;
        ctx.translate(iconLeft, iconTop);
        ctx.scale(iconSize / 24, iconSize / 24);
        ctx.strokeStyle = this.getThemeColor('cellTextColor');
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        const path = this.getListArrowPath2D();
        if (path) {
          ctx.stroke(path);
        } else {
          ctx.beginPath();
          ctx.moveTo(6, 9);
          ctx.lineTo(12, 15);
          ctx.lineTo(18, 9);
          ctx.stroke();
        }
        ctx.restore();
      }
    }

    // Flag any out-of-list value regardless of onInvalid mode — an invalid
    // value can arrive via paste / API / pre-existing content even under a
    // reject rule, and would otherwise be stored with no visual indication.
    if (!isValidListValue(rule, cell?.v)) {
      this.drawCornerMarker(ctx, rect.left + rect.width, rect.top, '#ea4335');
    }
  }

  /**
   * Renders row headers within a clip range.
   */
  private renderRowHeaders(
    ctx: CanvasRenderingContext2D,
    rowStart: number,
    rowEnd: number,
    scrollTop: number,
    clipTop: number,
    clipBottom: number,
    activeCell: Ref,
    selectionType?: SelectionType,
    selectionRange?: Range,
    rowDim?: DimensionIndex,
    _colDim?: DimensionIndex,
  ): void {
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, clipTop, RowHeaderWidth, clipBottom - clipTop);
    ctx.clip();

    for (let row = rowStart; row <= rowEnd; row++) {
      const rowOffset = rowDim
        ? rowDim.getOffset(row)
        : DefaultCellHeight * (row - 1);
      const rowHeight = rowDim ? rowDim.getSize(row) : DefaultCellHeight;
      if (rowHeight <= 0) {
        continue;
      }
      const x = 0;
      const y = rowOffset + DefaultCellHeight - scrollTop;
      const isRowSelected =
        selectionType === 'all' ||
        (selectionType === 'row' &&
          selectionRange &&
          row >= selectionRange[0].r &&
          row <= selectionRange[1].r);
      this.renderHeader(
        ctx,
        x,
        y,
        RowHeaderWidth,
        rowHeight,
        String(row),
        activeCell.r === row,
        isRowSelected || false,
      );
    }

    ctx.restore();
  }

  /**
   * Renders the freeze line separators.
   */
  private renderFreezeLines(
    ctx: CanvasRenderingContext2D,
    viewport: BoundingRect,
    frozenWidth: number,
    frozenHeight: number,
    gapX: number,
    gapY: number,
  ): void {
    ctx.strokeStyle = this.getThemeColor('freezeLineColor');
    ctx.lineWidth = FreezeHandleThickness;

    if (frozenHeight > 0) {
      const y = DefaultCellHeight + frozenHeight + gapY / 2;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(viewport.width, y);
      ctx.stroke();
    }

    if (frozenWidth > 0) {
      const x = RowHeaderWidth + frozenWidth + gapX / 2;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, viewport.height);
      ctx.stroke();
    }
  }

  /**
   * Renders the freeze drag handles at the corner header or at freeze line positions.
   */
  private renderFreezeHandles(
    ctx: CanvasRenderingContext2D,
    freeze: FreezeState,
    hoverHandle: 'row' | 'column' | null,
  ): void {
    const hasFrozen = freeze.frozenRows > 0 || freeze.frozenCols > 0;
    const t = FreezeHandleThickness;

    // --- Row freeze handle (horizontal bar spanning full row-header width) ---
    // Sits at the bottom edge of the header row (or at the gap center)
    const rowBarY =
      hasFrozen && freeze.frozenRows > 0
        ? DefaultCellHeight + freeze.frozenHeight + freeze.gapY / 2 - t / 2
        : DefaultCellHeight - t;
    const isRowHover = hoverHandle === 'row';

    ctx.fillStyle = isRowHover
      ? this.getThemeColor('freezeHandleHoverColor')
      : this.getThemeColor('freezeHandleColor');
    ctx.fillRect(0, rowBarY, RowHeaderWidth, t);

    // --- Column freeze handle (vertical bar spanning full column-header height) ---
    // Sits at the right edge of the row-header column (or at the gap center)
    const colBarX =
      hasFrozen && freeze.frozenCols > 0
        ? RowHeaderWidth + freeze.frozenWidth + freeze.gapX / 2 - t / 2
        : RowHeaderWidth - t;
    const isColHover = hoverHandle === 'column';

    ctx.fillStyle = isColHover
      ? this.getThemeColor('freezeHandleHoverColor')
      : this.getThemeColor('freezeHandleColor');
    ctx.fillRect(colBarX, 0, t, DefaultCellHeight);
  }

  /**
   * Draws a button-shaped indicator with two arrows pointing outward.
   * For rows: ▲▼ stacked vertically, left-aligned in row header.
   * For cols: ◄► side-by-side, top-aligned in column header.
   */
  private drawHiddenButton(
    ctx: CanvasRenderingContext2D,
    cx: number,
    cy: number,
    axis: 'row' | 'column',
    isHover: boolean,
  ): void {
    const bgColor = isHover
      ? this.getThemeColor('resizeHandleColor')
      : this.getThemeColor('headerBGColor');
    const arrowColor = isHover ? '#fff' : this.getThemeColor('cellTextColor');

    if (axis === 'row') {
      const btnW = HiddenBtnArrowSize * 2 + HiddenBtnPadding * 2;
      const btnH =
        HiddenBtnArrowSize * 2 + HiddenBtnArrowGap + HiddenBtnPadding * 2;
      const bx = cx - btnW / 2;
      const by = cy - btnH / 2;

      ctx.beginPath();
      ctx.roundRect(bx, by, btnW, btnH, HiddenBtnRadius);
      ctx.fillStyle = bgColor;
      ctx.fill();
      if (isHover) {
        ctx.strokeStyle = this.getThemeColor('resizeHandleColor');
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      // ▲ arrow (top)
      const topAy = cy - HiddenBtnArrowGap / 2 - HiddenBtnArrowSize / 2;
      ctx.fillStyle = arrowColor;
      ctx.beginPath();
      ctx.moveTo(cx, topAy - HiddenBtnArrowSize);
      ctx.lineTo(cx - HiddenBtnArrowSize, topAy + HiddenBtnArrowSize / 2);
      ctx.lineTo(cx + HiddenBtnArrowSize, topAy + HiddenBtnArrowSize / 2);
      ctx.closePath();
      ctx.fill();

      // ▼ arrow (bottom)
      const botAy = cy + HiddenBtnArrowGap / 2 + HiddenBtnArrowSize / 2;
      ctx.beginPath();
      ctx.moveTo(cx, botAy + HiddenBtnArrowSize);
      ctx.lineTo(cx - HiddenBtnArrowSize, botAy - HiddenBtnArrowSize / 2);
      ctx.lineTo(cx + HiddenBtnArrowSize, botAy - HiddenBtnArrowSize / 2);
      ctx.closePath();
      ctx.fill();
    } else {
      const btnW =
        HiddenBtnArrowSize * 2 + HiddenBtnArrowGap + HiddenBtnPadding * 2;
      const btnH = HiddenBtnArrowSize * 2 + HiddenBtnPadding * 2;
      const bx = cx - btnW / 2;
      const by = cy - btnH / 2;

      ctx.beginPath();
      ctx.roundRect(bx, by, btnW, btnH, HiddenBtnRadius);
      ctx.fillStyle = bgColor;
      ctx.fill();
      if (isHover) {
        ctx.strokeStyle = this.getThemeColor('resizeHandleColor');
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      // ◄ arrow (left)
      const leftAx = cx - HiddenBtnArrowGap / 2 - HiddenBtnArrowSize / 2;
      ctx.fillStyle = arrowColor;
      ctx.beginPath();
      ctx.moveTo(leftAx - HiddenBtnArrowSize, cy);
      ctx.lineTo(leftAx + HiddenBtnArrowSize / 2, cy - HiddenBtnArrowSize);
      ctx.lineTo(leftAx + HiddenBtnArrowSize / 2, cy + HiddenBtnArrowSize);
      ctx.closePath();
      ctx.fill();

      // ► arrow (right)
      const rightAx = cx + HiddenBtnArrowGap / 2 + HiddenBtnArrowSize / 2;
      ctx.beginPath();
      ctx.moveTo(rightAx + HiddenBtnArrowSize, cy);
      ctx.lineTo(rightAx - HiddenBtnArrowSize / 2, cy - HiddenBtnArrowSize);
      ctx.lineTo(rightAx - HiddenBtnArrowSize / 2, cy + HiddenBtnArrowSize);
      ctx.closePath();
      ctx.fill();
    }
  }

  /**
   * Renders button-shaped arrow markers in row headers at hidden row boundaries.
   * Button is left-aligned in the row header so it doesn't cover row numbers.
   */
  private renderHiddenRowIndicators(
    ctx: CanvasRenderingContext2D,
    rowStart: number,
    rowEnd: number,
    scrollTop: number,
    clipTop: number,
    clipBottom: number,
    rowDim: DimensionIndex | undefined,
    hiddenRows: Set<number>,
    hoverBoundary: number | null,
  ): void {
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, clipTop, RowHeaderWidth, clipBottom - clipTop);
    ctx.clip();

    const btnW = HiddenBtnArrowSize * 2 + HiddenBtnPadding * 2;
    // Left-aligned: button center at left edge + half button width + margin
    const cx = btnW / 2 + 1;

    for (let row = rowStart; row <= rowEnd + 1; row++) {
      // Hidden rows above this boundary
      if (!hiddenRows.has(row) && row > 1 && hiddenRows.has(row - 1)) {
        const isHover = hoverBoundary === row;
        const rowOffset = rowDim
          ? rowDim.getOffset(row)
          : DefaultCellHeight * (row - 1);
        const y = rowOffset + DefaultCellHeight - scrollTop;
        this.drawHiddenButton(ctx, cx, y, 'row', isHover);
      }
      // Hidden rows below this boundary
      if (!hiddenRows.has(row) && hiddenRows.has(row + 1)) {
        const isHover = hoverBoundary === row;
        const rowOffset = rowDim
          ? rowDim.getOffset(row)
          : DefaultCellHeight * (row - 1);
        const rowHeight = rowDim ? rowDim.getSize(row) : DefaultCellHeight;
        const y = rowOffset + DefaultCellHeight - scrollTop + rowHeight;
        this.drawHiddenButton(ctx, cx, y, 'row', isHover);
      }
    }

    ctx.restore();
  }

  /**
   * Renders button-shaped arrow markers in column headers at hidden column
   * boundaries. Button is top-aligned in the column header so it doesn't
   * cover column labels.
   */
  private renderHiddenColumnIndicators(
    ctx: CanvasRenderingContext2D,
    colStart: number,
    colEnd: number,
    scrollLeft: number,
    clipLeft: number,
    clipRight: number,
    colDim: DimensionIndex | undefined,
    hiddenColumns: Set<number>,
    hoverBoundary: number | null,
  ): void {
    ctx.save();
    ctx.beginPath();
    ctx.rect(clipLeft, 0, clipRight - clipLeft, DefaultCellHeight);
    ctx.clip();

    const btnH = HiddenBtnArrowSize * 2 + HiddenBtnPadding * 2;
    // Top-aligned: button center at top edge + half button height + margin
    const cy = btnH / 2 + 1;

    for (let col = colStart; col <= colEnd + 1; col++) {
      // Hidden columns to the left
      if (!hiddenColumns.has(col) && col > 1 && hiddenColumns.has(col - 1)) {
        const isHover = hoverBoundary === col;
        const colOffset = colDim
          ? colDim.getOffset(col)
          : DefaultCellWidth * (col - 1);
        const x = RowHeaderWidth + colOffset - scrollLeft;
        this.drawHiddenButton(ctx, x, cy, 'column', isHover);
      }
      // Hidden columns to the right
      if (!hiddenColumns.has(col) && hiddenColumns.has(col + 1)) {
        const isHover = hoverBoundary === col;
        const colOffset = colDim
          ? colDim.getOffset(col)
          : DefaultCellWidth * (col - 1);
        const colWidth = colDim ? colDim.getSize(col) : DefaultCellWidth;
        const x = RowHeaderWidth + colOffset - scrollLeft + colWidth;
        this.drawHiddenButton(ctx, x, cy, 'column', isHover);
      }
    }

    ctx.restore();
  }

  private renderHeader(
    ctx: CanvasRenderingContext2D,
    x: number,
    y: number,
    width: number,
    height: number,
    label: string,
    selected: boolean,
    fullSelected: boolean = false,
  ): void {
    if (width <= 0 || height <= 0) {
      return;
    }
    ctx.fillStyle = fullSelected
      ? this.getThemeColor('headerSelectedBGColor')
      : selected
        ? this.getThemeColor('headerActiveBGColor')
        : this.getThemeColor('headerBGColor');
    ctx.fillRect(x, y, width, height);
    ctx.strokeStyle = this.getThemeColor('cellBorderColor');
    ctx.lineWidth = CellBorderWidth;
    ctx.strokeRect(x, y, width, height);
    ctx.fillStyle = this.getThemeColor('cellTextColor');
    ctx.textAlign = HeaderTextAlign;
    ctx.font = selected || fullSelected ? 'bold 10px Arial' : '10px Arial';
    ctx.fillText(label, x + width / 2, y + Math.min(15, height - 4));
  }

  private renderCellBackground(
    ctx: CanvasRenderingContext2D,
    id: Ref,
    cell: Cell | undefined,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    effectiveStyle?: CellStyle,
    mergeSpan?: MergeSpan,
    hideLeftBorder: boolean = false,
    hideRightBorder: boolean = false,
  ): void {
    const rect = this.toCellRect(id, scroll, rowDim, colDim, mergeSpan);
    const style = effectiveStyle ?? cell?.s;

    ctx.fillStyle = style?.bg || this.getThemeColor('cellBGColor');
    ctx.fillRect(rect.left, rect.top, rect.width, rect.height);

    ctx.beginPath();
    ctx.strokeStyle = this.getThemeColor('cellBorderColor');
    ctx.lineWidth = CellBorderWidth;
    if (!hideLeftBorder) {
      ctx.moveTo(rect.left, rect.top);
      ctx.lineTo(rect.left, rect.top + rect.height);
    }
    if (!hideRightBorder) {
      const x = rect.left + rect.width;
      ctx.moveTo(x, rect.top);
      ctx.lineTo(x, rect.top + rect.height);
    }
    ctx.moveTo(rect.left, rect.top);
    ctx.lineTo(rect.left + rect.width, rect.top);
    ctx.moveTo(rect.left, rect.top + rect.height);
    ctx.lineTo(rect.left + rect.width, rect.top + rect.height);
    ctx.stroke();
  }

  private renderCellCustomBorders(
    ctx: CanvasRenderingContext2D,
    id: Ref,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    style?: CellStyle,
    mergeSpan?: MergeSpan,
  ): void {
    if (!style || (!style.bt && !style.br && !style.bb && !style.bl)) {
      return;
    }

    const rect = this.toCellRect(id, scroll, rowDim, colDim, mergeSpan);
    ctx.beginPath();
    ctx.strokeStyle = this.getThemeColor('customBorderColor');
    ctx.lineWidth = CustomCellBorderWidth;

    if (style.bt) {
      ctx.moveTo(rect.left, rect.top);
      ctx.lineTo(rect.left + rect.width, rect.top);
    }
    if (style.br) {
      const x = rect.left + rect.width;
      ctx.moveTo(x, rect.top);
      ctx.lineTo(x, rect.top + rect.height);
    }
    if (style.bb) {
      const y = rect.top + rect.height;
      ctx.moveTo(rect.left, y);
      ctx.lineTo(rect.left + rect.width, y);
    }
    if (style.bl) {
      ctx.moveTo(rect.left, rect.top);
      ctx.lineTo(rect.left, rect.top + rect.height);
    }

    ctx.stroke();
  }

  private renderCellContent(
    ctx: CanvasRenderingContext2D,
    id: Ref,
    cell: Cell | undefined,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    effectiveStyle?: CellStyle,
    grid?: Grid,
    colEnd?: number,
    mergeSpan?: MergeSpan,
    overflowEndCol?: number,
  ): void {
    const rect = this.toCellRect(id, scroll, rowDim, colDim, mergeSpan);
    const style = effectiveStyle ?? cell?.s;

    const rawData = cell?.v || '';
    if (rawData) {
      const data = formatValue(rawData, style?.nf, style?.dp, {
        currency: style?.cu,
      });
      const lines = data.split('\n');

      // Build font string (needed for measuring text width)
      const fontStr = this.toCellFont(style);

      // Compute overflow clip width for single-line, left-aligned text
      let clipWidth = rect.width;
      const align = style?.al || defaultAlign(rawData, style?.nf);
      if (!mergeSpan && overflowEndCol && colDim && overflowEndCol > id.c) {
        let extraWidth = 0;
        for (let nextCol = id.c + 1; nextCol <= overflowEndCol; nextCol++) {
          extraWidth += colDim.getSize(nextCol);
        }
        clipWidth = rect.width + extraWidth;
      } else if (
        !mergeSpan &&
        lines.length === 1 &&
        align === 'left' &&
        grid &&
        colDim &&
        colEnd
      ) {
        ctx.save();
        ctx.font = fontStr;
        const textWidth = ctx.measureText(data).width + CellPaddingX * 2;
        ctx.restore();

        if (textWidth > rect.width) {
          let extraWidth = 0;
          for (let nextCol = id.c + 1; nextCol <= colEnd; nextCol++) {
            const neighborCell = grid.get(toSref({ r: id.r, c: nextCol }));
            if (neighborCell && (neighborCell.v || neighborCell.f)) break;
            const neighborWidth = colDim.getSize(nextCol);
            extraWidth += neighborWidth;
            if (rect.width + extraWidth >= textWidth) break;
          }
          clipWidth = rect.width + extraWidth;
        }
      }

      ctx.save();
      ctx.beginPath();
      ctx.rect(rect.left, rect.top, clipWidth, rect.height);
      ctx.clip();
      ctx.fillStyle = style?.tc || this.getThemeColor('cellTextColor');

      ctx.font = fontStr;
      ctx.textBaseline = 'top';

      // Compute text alignment
      let textX: number;
      if (align === 'center') {
        ctx.textAlign = 'center';
        textX = rect.left + rect.width / 2;
      } else if (align === 'right') {
        ctx.textAlign = 'right';
        textX = rect.left + rect.width - CellPaddingX;
      } else {
        ctx.textAlign = 'left';
        textX = rect.left + CellPaddingX;
      }

      // Compute vertical alignment offset
      const vAlign = style?.va || 'top';
      const totalTextHeight = getTextBlockHeight(lines.length);
      let baseY: number;
      if (vAlign === 'middle') {
        baseY = rect.top + (rect.height - totalTextHeight) / 2;
      } else if (vAlign === 'bottom') {
        baseY = rect.top + rect.height - totalTextHeight - CellPaddingY;
      } else {
        baseY = rect.top + CellPaddingY;
      }

      for (let i = 0; i < lines.length; i++) {
        const textY = baseY + i * (CellFontSize * CellLineHeight);
        ctx.fillText(lines[i], textX, textY);

        // Underline
        if (style?.u) {
          const metrics = ctx.measureText(lines[i]);
          const lineY = textY + CellFontSize + 1;
          let lineStartX: number;
          if (align === 'center') {
            lineStartX = textX - metrics.width / 2;
          } else if (align === 'right') {
            lineStartX = textX - metrics.width;
          } else {
            lineStartX = textX;
          }
          ctx.beginPath();
          ctx.strokeStyle = style?.tc || this.getThemeColor('cellTextColor');
          ctx.lineWidth = 1;
          ctx.moveTo(lineStartX, lineY);
          ctx.lineTo(lineStartX + metrics.width, lineY);
          ctx.stroke();
        }

        // Strikethrough
        if (style?.st) {
          const metrics = ctx.measureText(lines[i]);
          const lineY = textY + CellFontSize / 2;
          let lineStartX: number;
          if (align === 'center') {
            lineStartX = textX - metrics.width / 2;
          } else if (align === 'right') {
            lineStartX = textX - metrics.width;
          } else {
            lineStartX = textX;
          }
          ctx.beginPath();
          ctx.strokeStyle = style?.tc || this.getThemeColor('cellTextColor');
          ctx.lineWidth = 1;
          ctx.moveTo(lineStartX, lineY);
          ctx.lineTo(lineStartX + metrics.width, lineY);
          ctx.stroke();
        }
      }
      ctx.restore();
    }
  }

  private buildTextOverflowRenderData(
    ctx: CanvasRenderingContext2D,
    rowStart: number,
    rowEnd: number,
    colStart: number,
    colEnd: number,
    grid: Grid | undefined,
    colDim?: DimensionIndex,
    mergeData?: {
      anchors: Map<string, MergeSpan>;
      coverToAnchor: Map<string, string>;
    },
    resolveCellStyle?: (
      row: number,
      col: number,
      cell?: Cell,
    ) => CellStyle | undefined,
  ): TextOverflowRenderData | undefined {
    if (!grid || !colDim) return undefined;

    const anchorToEndCol = new Map<string, number>();
    const hiddenVerticalBoundaries = new Set<string>();

    ctx.save();
    for (let row = rowStart; row <= rowEnd; row++) {
      for (let col = colStart; col <= colEnd; col++) {
        const sref = toSref({ r: row, c: col });
        if (
          mergeData?.coverToAnchor.has(sref) ||
          mergeData?.anchors.has(sref)
        ) {
          continue;
        }

        const cell = grid.get(sref);
        const rawData = cell?.v || '';
        if (!rawData) {
          continue;
        }

        const style = resolveCellStyle?.(row, col, cell);

        const align = style?.al || defaultAlign(rawData, style?.nf);
        if (align !== 'left') {
          continue;
        }

        const data = formatValue(rawData, style?.nf, style?.dp, {
          currency: style?.cu,
        });
        const lines = data.split('\n');
        if (lines.length !== 1) {
          continue;
        }

        const cellWidth = colDim.getSize(col);
        ctx.font = this.toCellFont(style);
        const textWidth = ctx.measureText(data).width + CellPaddingX * 2;
        if (textWidth <= cellWidth) {
          continue;
        }

        let width = cellWidth;
        let overflowEndCol = col;
        for (let nextCol = col + 1; nextCol <= colEnd; nextCol++) {
          const leftStyle = resolveCellStyle?.(
            row,
            nextCol - 1,
            grid.get(toSref({ r: row, c: nextCol - 1 })),
          );
          const rightStyle = resolveCellStyle?.(
            row,
            nextCol,
            grid.get(toSref({ r: row, c: nextCol })),
          );
          if (leftStyle?.br || rightStyle?.bl) {
            break;
          }

          const nextSref = toSref({ r: row, c: nextCol });
          if (
            mergeData?.coverToAnchor.has(nextSref) ||
            mergeData?.anchors.has(nextSref)
          ) {
            break;
          }
          const neighbor = grid.get(nextSref);
          if (neighbor && (neighbor.v || neighbor.f)) {
            break;
          }
          width += colDim.getSize(nextCol);
          overflowEndCol = nextCol;
          if (width >= textWidth) {
            break;
          }
        }

        if (overflowEndCol > col) {
          anchorToEndCol.set(sref, overflowEndCol);
          for (
            let boundaryCol = col;
            boundaryCol < overflowEndCol;
            boundaryCol++
          ) {
            hiddenVerticalBoundaries.add(
              this.verticalBoundaryKey(row, boundaryCol),
            );
          }
        }
      }
    }
    ctx.restore();

    if (anchorToEndCol.size === 0) {
      return undefined;
    }

    return { anchorToEndCol, hiddenVerticalBoundaries };
  }

  private resolveEffectiveStyle(
    row: number,
    col: number,
    cell?: Cell,
    sheetStyle?: CellStyle,
    colStyles?: Map<number, CellStyle>,
    rowStyles?: Map<number, CellStyle>,
    rangeStyles?: RangeStylePatch[],
    conditionalFormats?: ConditionalFormatRule[],
  ): CellStyle | undefined {
    const cStyle = colStyles?.get(col);
    const rStyle = rowStyles?.get(row);
    const rangeStyle = rangeStyles
      ? resolveRangeStyleAt(rangeStyles, row, col)
      : undefined;
    const conditionalStyle = conditionalFormats
      ? resolveConditionalFormatStyleAt(conditionalFormats, row, col, cell)
      : undefined;
    if (
      !sheetStyle &&
      !cStyle &&
      !rStyle &&
      !rangeStyle &&
      !cell?.s &&
      !conditionalStyle
    ) {
      return undefined;
    }
    return {
      ...sheetStyle,
      ...cStyle,
      ...rStyle,
      ...rangeStyle,
      ...cell?.s,
      ...conditionalStyle,
    };
  }

  /**
   * Builds merge lookup maps for rendering.
   */
  private buildMergeRenderData(
    merges?: Map<string, MergeSpan>,
  ):
    | { anchors: Map<string, MergeSpan>; coverToAnchor: Map<string, string> }
    | undefined {
    if (!merges || merges.size === 0) return undefined;
    const anchors = new Map<string, MergeSpan>();
    const coverToAnchor = new Map<string, string>();

    for (const [anchorSref, span] of merges) {
      anchors.set(anchorSref, span);
      const anchor = parseRef(anchorSref);
      for (let r = anchor.r; r < anchor.r + span.rs; r++) {
        for (let c = anchor.c; c < anchor.c + span.cs; c++) {
          const sref = toSref({ r, c });
          if (sref === anchorSref) continue;
          coverToAnchor.set(sref, anchorSref);
        }
      }
    }
    return { anchors, coverToAnchor };
  }

  /**
   * Returns the rect for a regular or merged anchor cell.
   */
  private toCellRect(
    id: Ref,
    scroll: Position,
    rowDim?: DimensionIndex,
    colDim?: DimensionIndex,
    mergeSpan?: MergeSpan,
  ): BoundingRect {
    const start = toBoundingRect(id, scroll, rowDim, colDim);
    if (!mergeSpan || (mergeSpan.rs === 1 && mergeSpan.cs === 1)) {
      return start;
    }
    const end = toBoundingRect(
      { r: id.r + mergeSpan.rs - 1, c: id.c + mergeSpan.cs - 1 },
      scroll,
      rowDim,
      colDim,
    );
    return {
      left: start.left,
      top: start.top,
      width: end.left + end.width - start.left,
      height: end.top + end.height - start.top,
    };
  }

  private toCellFont(style?: CellStyle): string {
    const fontParts: string[] = [];
    if (style?.b) fontParts.push('bold');
    if (style?.i) fontParts.push('italic');
    fontParts.push(`${CellFontSize}px Arial`);
    return fontParts.join(' ');
  }

  private verticalBoundaryKey(row: number, col: number): string {
    return `${row}:${col}`;
  }

  private getThemeColor(key: ThemeKey): string {
    return getThemeColor(this.theme, key);
  }

  public cleanup(): void {
    this.canvas.remove();
  }
}

/**
 * Reference type represents reference to cells in the sheet.
 */
export type Reference = Sref | Srng;

/**
 * Direction type represents the direction of the movement.
 */
export type Direction = 'up' | 'down' | 'left' | 'right';

/**
 * Axis type represents the axis of the sheet.
 */
export type Axis = 'row' | 'column';

/**
 * Sref type represents a reference to a cell in the sheet.
 * e.g. A1, B2, C3, etc.
 */
export type Sref = string;

/**
 * Srng type represents a range of cells in the sheet.
 * e.g. A1:B2, C3:D4, etc.
 */
export type Srng = string;

/**
 * Ref type represents the id of a cell in the sheet.
 */
export type Ref = {
  r: number;
  c: number;
};

/**
 * ARef (Absolute-aware Ref) extends Ref with optional absolute-reference flags.
 * Used during formula relocation to decide which axes should stay fixed.
 */
export type ARef = Ref & {
  absCol?: boolean;
  absRow?: boolean;
};

/**
 * Range type represents a range of cells in the sheet.
 */
export type Range = [Ref, Ref];

/**
 * Ranges type represents multiple disjoint ranges.
 */
export type Ranges = Range[];

/**
 * TextAlign represents the horizontal text alignment of a cell.
 */
export type TextAlign = 'left' | 'center' | 'right';

/**
 * VerticalAlign represents the vertical text alignment of a cell.
 */
export type VerticalAlign = 'top' | 'middle' | 'bottom';

/**
 * NumberFormat represents the number format of a cell.
 */
export type NumberFormat = 'plain' | 'number' | 'currency' | 'percent' | 'date';

/**
 * BorderPreset represents a border application preset for a selected range.
 */
export type BorderPreset =
  | 'all'
  | 'outer'
  | 'inner'
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'clear';

/**
 * CellStyle represents the formatting style of a cell.
 */
export type CellStyle = {
  b?: boolean; // bold
  i?: boolean; // italic
  u?: boolean; // underline
  st?: boolean; // strikethrough
  bt?: boolean; // top border
  br?: boolean; // right border
  bb?: boolean; // bottom border
  bl?: boolean; // left border
  tc?: string; // text color (#hex)
  bg?: string; // background color (#hex)
  al?: TextAlign; // horizontal alignment
  va?: VerticalAlign; // vertical alignment
  nf?: NumberFormat; // number format
  cu?: string; // currency code (e.g. KRW, USD) when nf is currency
  dp?: number; // decimal places (for number/currency/percent formats)
};

/**
 * Conditional formatting operators.
 */
export type ConditionalFormatOperator =
  | 'isEmpty'
  | 'isNotEmpty'
  | 'textContains'
  | 'greaterThan'
  | 'between'
  | 'dateBefore'
  | 'dateAfter';

/**
 * Conditional formatting supports a focused subset of text/fill styles.
 */
export type ConditionalFormatStyle = Partial<
  Pick<CellStyle, 'b' | 'i' | 'u' | 'tc' | 'bg'>
>;

/**
 * Conditional formatting rule.
 */
export type ConditionalFormatRule = {
  id: string;
  ranges: Range[];
  op: ConditionalFormatOperator;
  value?: string;
  value2?: string;
  style: ConditionalFormatStyle;
};

/**
 * DataValidationKind enumerates the in-cell control kinds.
 */
export type DataValidationKind = 'checkbox' | 'list' | 'date';

/**
 * DataValidationOperator enumerates the comparison operators. Date operators
 * ship first; number/text operators reuse this union later.
 */
export type DataValidationOperator =
  | 'dateValid'
  | 'dateEquals'
  | 'dateBefore'
  | 'dateOnOrBefore'
  | 'dateAfter'
  | 'dateOnOrAfter'
  | 'dateBetween'
  | 'dateNotBetween';

/**
 * DataValidationRule is a worksheet-level, range-scoped validation/control
 * rule. The control is a special render of a typed cell value — the cell
 * itself holds the value (boolean TRUE/FALSE, ISO date, or list text).
 */
export type DataValidationRule = {
  id: string;
  ranges: Range[];
  kind: DataValidationKind;
  onInvalid?: 'reject' | 'warning'; // list/date only; ignored for checkbox

  // kind: 'list'
  list?: string[];
  showArrow?: boolean;

  // kind: 'checkbox'
  checkedValue?: string;
  uncheckedValue?: string;

  // kind: 'date' (operator + fixed-date operands; future: number/text)
  operator?: DataValidationOperator;
  values?: string[]; // ISO operands; length by operator (0/1/2)
};

/**
 * Cell type represents a cell in the sheet.
 *
 * Spill fields support dynamic-array formulas (e.g. MMULT, MINVERSE):
 *   - The anchor cell (the one with the formula) stores `spillRows`/`spillCols`
 *     so the calculator knows how many ghost cells to clear on recalculation.
 *   - Each ghost cell stores `spillAnchor` pointing back to the anchor's Sref.
 */
export type Cell = {
  v?: string;
  f?: string;
  s?: CellStyle;
  spillRows?: number;
  spillCols?: number;
  spillAnchor?: Sref;
  spillBlocked?: boolean;
};

/**
 * MergeSpan represents a merged cell block size from an anchor cell.
 * `rs` = row span, `cs` = column span.
 */
export type MergeSpan = {
  rs: number;
  cs: number;
};

/**
 * Filter operators for column-level filtering.
 */
export type FilterOperator =
  | 'contains'
  | 'notContains'
  | 'equals'
  | 'notEquals'
  | 'isEmpty'
  | 'isNotEmpty'
  | 'in';

/**
 * Filter condition for a single column.
 */
export type FilterCondition = {
  op: FilterOperator;
  value?: string;
  values?: string[];
};

/**
 * FilterState stores filter range, per-column criteria, and computed hidden rows.
 */
export type FilterState = {
  range: Range;
  columns: Record<string, FilterCondition>;
  hiddenRows: number[];
};

/**
 * HiddenState stores manually hidden row and column indices.
 */
export type HiddenState = {
  rows: number[];
  columns: number[];
};

/**
 * AggregateFunction represents the aggregation functions available in pivot tables.
 */
export type AggregateFunction =
  | 'SUM'
  | 'COUNT'
  | 'COUNTA'
  | 'AVERAGE'
  | 'MIN'
  | 'MAX';

/**
 * PivotFieldSort represents the sort direction for a pivot field.
 */
export type PivotFieldSort = 'asc' | 'desc';

/**
 * PivotField represents a row or column field in a pivot table.
 */
export type PivotField = {
  sourceColumn: number;
  label: string;
  sort?: PivotFieldSort;
};

/**
 * PivotValueField represents a value field with an aggregation function.
 */
export type PivotValueField = PivotField & {
  aggregation: AggregateFunction;
};

/**
 * PivotFilterField represents a filter field with hidden values.
 */
export type PivotFilterField = PivotField & {
  hiddenValues: string[];
};

/**
 * PivotTableDefinition describes the full configuration of a pivot table.
 */
export type PivotTableDefinition = {
  id: string;
  sourceTabId: string;
  sourceRange: string;
  rowFields: PivotField[];
  columnFields: PivotField[];
  valueFields: PivotValueField[];
  filterFields: PivotFilterField[];
  showTotals: {
    rows: boolean;
    columns: boolean;
  };
};

/**
 * PivotRecord represents a single data record as an array of string values.
 */
export type PivotRecord = string[];

/**
 * GroupNode represents a node in the pivot table grouping tree.
 */
export type GroupNode = {
  value: string;
  children: GroupNode[];
  records: number[];
};

/**
 * PivotCellType represents the type of a cell in the pivot table output.
 */
export type PivotCellType =
  | 'rowHeader'
  | 'colHeader'
  | 'value'
  | 'total'
  | 'empty';

/**
 * PivotCellFormat is the subset of CellStyle that a pivot cell inherits from
 * its source column (number format, decimal places, currency code).
 */
export type PivotCellFormat = Pick<CellStyle, 'nf' | 'dp' | 'cu'>;

/**
 * PivotCell represents a single cell in the pivot table output.
 */
export type PivotCell = {
  value: string;
  type: PivotCellType;
  /**
   * Format inherited from the source column, applied to the materialized
   * cell so labels/values render with the source's number/date format.
   */
  format?: PivotCellFormat;
};

/**
 * PivotResult represents the computed output of a pivot table.
 */
export type PivotResult = {
  cells: PivotCell[][];
  rowCount: number;
  colCount: number;
};

/**
 * Grid type represents a grid of rows and columns.
 */
export type Grid = Map<Sref, Cell>;

/**
 * SelectionType represents the type of selection.
 */
export type SelectionType = 'cell' | 'row' | 'column' | 'all';

/**
 * GridResolver resolves cell data from other sheets.
 * Takes a sheet name + set of cell refs, returns a Grid with those cells' data,
 * or undefined if the sheet doesn't exist.
 */
export type GridResolver = (
  sheetName: string,
  refs: Set<Sref>,
) => Grid | undefined;

/**
 * FormulaResolver returns formula strings from other sheets.
 * Takes a sheet name, returns a Map from local Sref to formula string,
 * or undefined if the sheet doesn't exist.
 */
export type FormulaResolver = (
  sheetName: string,
) => Map<Sref, string> | undefined;
